/* ===== Buttons ===== */
.btn{
  display:inline-flex;align-items:center;gap:6px;
  padding:8px 16px;border-radius:7px;border:1px solid transparent;
  background:var(--primary);color:#fff;cursor:pointer;
  font-size:13px;font-weight:500;font-family:inherit;
  transition:all .12s ease;
  text-decoration:none;
}
.btn:hover{background:var(--primary-700);text-decoration:none;color:#fff;transform:translateY(-1px);box-shadow:var(--shadow-sm)}
.btn-ghost{background:transparent;color:#fff;border:1px solid rgba(255,255,255,.4)}
.btn-ghost:hover{background:rgba(255,255,255,.12);transform:none}
.btn-secondary{background:#fff;color:var(--primary);border-color:var(--border)}
