arguments.new_string:
/* ===== Inline table action cells ===== */
td .action-bar{flex-wrap:nowrap;gap:4px}

/* ===== Responsive ===== */
@media (max-width: 900px){
  .grid-4{grid-template-columns:repeat(2,1fr)}
  .grid-3{grid-template-columns:1fr 1fr}
}

@media (max-width: 768px){
  /* Show hamburger, hide desktop toggle */
  .hamburger{display:flex}
  .sb-toggle{display:none}

  /* Sidebar becomes a fixed left drawer */
  .sidebar{
    position:fixed;
    top:0;bottom:0;left:0;
    width:260px !important;
    z-index:150;
    transform:translateX(-100%);
    transition:transform .25s cubic-bezier(.4,0,.2,1);
    padding-top:16px;
    overflow-y:auto;
  }
  .sidebar.open{transform:translateX(0)}

  /* Show mobile close button inside drawer */
  .sb-close-btn{
    display:flex;align-items:center;justify-content:flex-end;
    width:100%;padding:6px 14px 10px;background:none;border:none;
    cursor:pointer;color:rgba(255,255,255,.5);
  }
  .sb-close-btn:hover{color:#fff}
  .sb-close-btn svg{width:22px;height:22px}

  /* Hide desktop collapse button inside sidebar on mobile */
  .sb-collapse-btn{display:none}

  /* Show nav labels on mobile drawer */
  .sidebar .nav-label-text{opacity:1 !important;width:auto !important}
  .sidebar .nav-label{display:block !important;opacity:1}
  .sidebar a{padding:13px 22px;font-size:14px}

  /* Content full-width */
  .content{padding:16px}

  /* Topbar compact */
  .topbar-inner{padding:10px 14px;gap:10px}
  .brand .motto{display:none}
  .user-info{display:none}
  .brand .org{font-size:13px;letter-spacing:.8px}

  .grid-4,.grid-3{grid-template-columns:repeat(2,1fr)}
}

@media (max-width: 480px){
  .grid-4,.grid-3,.grid-2{grid-template-columns:1fr}
  .content{padding:12px}
  .page-header{flex-direction:column;gap:10px}
  .page-header .action-bar{width:100%;justify-content:flex-end}
  .form-row{flex-direction:column}
  .form-group{min-width:unset}
}

